export function issueTableGroupsOptions(
  wsId: string,
  query: IssueTableQuerySpec,
  group: IssueTableGroupsRequest["group"],
) {
  return infiniteQueryOptions({
    queryKey: issueKeys.tableGroups(wsId, query, group),
    initialPageParam: null as string | null,
    queryFn: ({ pageParam }) =>
      api.listIssueTableGroups({
        query,
        group,
        page: { limit: 100, cursor: pageParam },
    }),
    getNextPageParam: (lastPage) => lastPage.next_cursor ?? undefined,
    placeholderData: keepPreviousData,
    retry: false,
  });
}

/** One independently-addressable Table branch page.
 *
 * Table keeps every cursor page under its own query key so a refreshed head
 * can detach stale tail cursors before their responses land. Keep the request,
 * key shape, transition placeholder, and retry policy together here — the
 * dynamic branch graph in views should not duplicate this API contract. */

export function issueTableRowPageOptions(
  wsId: string,
  request: IssueTableRowsRequest,
) {
  const cursor = request.page?.cursor ?? null;
  return queryOptions({
    queryKey: [
      ...issueKeys.tableRows(
        wsId,
        request.query,
        request.group,
        request.group_key,
        request.hierarchy.enabled,
        request.parent_id,
      ),
      "page",
      cursor,
    ] as const,
    queryFn: () => api.listIssueTableRows(request),
    placeholderData: keepPreviousData,
    retry: false,
    // Dynamic useQueries observers detach/reinstall as sibling branches enter
    // and leave the viewport. Keep an errored page errored until the user hits
    // Retry — but still let a successful-but-invalidated page refetch on
    // reattach, so a row page that gets WS-invalidated while its observer is
    // detached doesn't stay stranded stale under the global `staleTime: Infinity`
    // default (correct count, missing issue).
    //
    // Both guards are needed: `retryOnMount` covers a first-load error (no
    // data), while the `refetchOnMount` guard covers a background-refetch error
    // on a page that still holds data — TanStack flags such a page
    // `isInvalidated`, so a plain `refetchOnMount: true` would re-fire the
    // failing request on every reattach instead of waiting for explicit Retry.
    retryOnMount: false,
    refetchOnMount: (query) => query.state.status !== "error",
  });
}

export function issueTableFacetsOptions(
  wsId: string,
  request: IssueTableFacetsRequest,
) {
  return queryOptions({
    queryKey: issueKeys.tableFacets(wsId, request),
    queryFn: () => api.listIssueTableFacets(request),
  });
}

/**
 * CACHE SHAPE NOTE: The raw cache stores {@link ListIssuesCache} (buckets keyed
 * by status, each with `{ issues, total }`), and `select` flattens it to
 * `Issue[]` for consumers. Mutations and ws-updaters must use
 * `setQueryData<ListIssuesCache>(...)` and preserve the byStatus shape.
 *
 * Fetches the first page in one request and buckets it by category.
 */

export function issueListOptions(wsId: string, sort?: IssueSortParam) {
  return queryOptions({
    queryKey: issueKeys.listSorted(wsId, sort),
    queryFn: () => fetchFirstPages({}, sort),
    select: flattenIssueBuckets,
    placeholderData: keepPreviousData,
  });
}

/**
 * Page size for the scheduled-issue fetch. The Gantt view always pulls every
 * scheduled issue (no client pagination), so this is just the chunk size we
 * use to walk the server's `(limit, offset)` window until we hit `total`.
 *
 * Must not exceed the server's `ListIssues` page-size cap (100): the server
 * silently clamps larger values, and a clamped page would otherwise look like
 * a short final page.
 */
export const PROJECT_GANTT_PAGE_LIMIT = 100;

/**
 * Paranoia cap on the loop in {@link fetchProjectGanttIssues}. Real projects
 * shouldn't come close to this — a single project carrying 50k scheduled
 * issues is already a product problem, not a Gantt-rendering one — but the
 * guard prevents a buggy server `total` from spinning the loop forever.
 */
export const PROJECT_GANTT_MAX_ISSUES = 10_000;

export function projectGanttIssuesOptions(
  wsId: string,
  projectId: string,
  // The page's assignee-type tab narrows the Gantt exactly like every
  // other mode — same scope, same single mapping upstream.
  assigneeTypes?: IssueAssigneeType[],
) {
  return queryOptions({
    queryKey: issueKeys.projectGantt(wsId, projectId, assigneeTypes),
    queryFn: () => fetchProjectGanttIssues(projectId, assigneeTypes),
  });
}

/** The table endpoint caps a page here, so a longer sidebar list is fetched in pages. */
const SIDEBAR_MAX_PAGE = 100;

export function sidebarIssuesOptions(
  wsId: string,
  source: string,
  request: SidebarIssuesRequest,
  limit: number,
) {
  return queryOptions({
    queryKey: issueKeys.sidebar(wsId, source, request, limit),
    queryFn: () => listSidebarTableIssues(request.table, limit),
  });
}

export function issueIdentifierOptions(wsId: string, identifier: string) {
  return queryOptions({
    queryKey: issueKeys.identifier(wsId, identifier),
    // Keep this small, cacheable lookup alive when the last mention unmounts.
    // A remount can then share its request instead of aborting and restarting it.
    queryFn: async () => {
      try {
        return await api.getIssue(identifier);
      } catch (err) {
        // Unknown identifier / wrong workspace prefix → render as plain text.
        // Any other failure (401/5xx) must keep propagating so the query
        // can retry instead of being cached as "no such issue".
        if (err instanceof ApiError && err.status === 404) return null;
        throw err;
      }
    },
    // Identifier→issue mapping is effectively immutable; avoid refetch churn
    // when the same key renders across many comments/messages.
    staleTime: 5 * 60_000,
  });
}

export function childIssueProgressOptions(wsId: string) {
  return queryOptions({
    queryKey: issueKeys.childProgress(wsId),
    queryFn: () => api.getChildIssueProgress(),
    select: (data) => {
      const map = new Map<string, { done: number; total: number }>();
      for (const entry of data.progress) {
        map.set(entry.parent_issue_id, { done: entry.done, total: entry.total });
      }
      return map;
    },
  });
}

/** Both sides of an issue's duplicate relation: its original and its duplicates. */

export function issueDuplicatesOptions(wsId: string, id: string) {
  return queryOptions({
    queryKey: issueKeys.duplicates(wsId, id),
    queryFn: () => api.listIssueDuplicates(id),
    // Same reason as childIssuesOptions: a mark written while this workspace
    // is not the active realtime subscription would otherwise leave the
    // Infinity-stale snapshot wrong when the issue is opened again.
    refetchOnMount: "always",
  });
}

export function childIssuesOptions(wsId: string, id: string) {
  return queryOptions({
    queryKey: issueKeys.children(wsId, id),
    queryFn: () => api.listChildIssues(id).then((r) => r.issues),
    // Child creation can happen while this workspace is not the active
    // realtime subscription (for example, an agent creates it while a
    // desktop tab is showing another workspace). The global Infinity
    // staleTime would otherwise reuse an incomplete children snapshot when
    // the parent is opened again, with no later event guaranteed to heal it.
    refetchOnMount: "always",
  });
}

/**
 * Server cap on parent_ids per `GET /api/issues/children` request — must
 * match `listChildrenByParentsLimit` in server/go/internal/handler/issue.go.
 * Exceeding it returns 400, so the client chunks larger requests.
 */
export const CHILDREN_BY_PARENTS_CHUNK_SIZE = 200;

/**
 * Batched variant of {@link childIssuesOptions}: fetches children for all
 * given parents in `GET /api/issues/children?parent_ids=…` requests, chunked
 * to {@link CHILDREN_BY_PARENTS_CHUNK_SIZE} parents each. The queryFn also
 * hydrates each parent's per-parent issueKeys.children cache so other
 * surfaces (issue-detail sub-issues panel, set-parent modal) hit the primed
 * cache instead of re-fetching. Hydration happens in queryFn (not a
 * useEffect) to avoid the setQueryData → re-render → effect loop.
 *
 * Used by SwimLaneView to resolve parent lanes without an N-request fan-out.
 * parentIds must be sorted + deduplicated by the caller for a stable cache key.
 */

export function childrenByParentsOptions(
  wsId: string,
  parentIds: readonly string[],
  qc: QueryClient,
) {
  return queryOptions({
    queryKey: issueKeys.childrenByParents(wsId, parentIds),
    queryFn: () => fetchAndHydrateChildrenByParents(qc, wsId, parentIds),
    enabled: parentIds.length > 0,
  });
}

/**
 * Single-fetch timeline options. The endpoint returns the full ordered set of
 * comments + activities for an issue (server caps at 2000 as a safety net).
 * Cursor pagination was removed in #1929 — at observed data sizes (p99 ~30
 * entries per issue) it added complexity without a UX win and broke reply
 * threads at page boundaries.
 */

export function issueTimelineOptions(issueId: string) {
  return queryOptions({
    queryKey: issueKeys.timeline(issueId),
    queryFn: () => api.listTimeline(issueId),
  });
}

export function issueCommentThreadOptions(issueId: string, commentId: string) {
  return queryOptions({
    queryKey: issueKeys.commentThread(issueId, commentId),
    queryFn: async () => {
      const comments = await api.listComments(issueId, { thread: commentId });
      if (!comments.some((comment) => comment.id === commentId)) {
        throw new Error("Comment not found in thread");
      }
      return comments;
    },
  });
}

export function issueReactionsOptions(issueId: string) {
  return queryOptions({
    queryKey: issueKeys.reactions(issueId),
    queryFn: async () => {
      const issue = await api.getIssue(issueId);
      return issue.reactions ?? [];
    },
  });
}

export function issueSubscribersOptions(issueId: string) {
  return queryOptions({
    queryKey: issueKeys.subscribers(issueId),
    queryFn: () => api.listIssueSubscribers(issueId),
  });
}

// Reports arrive over realtime; the interval only re-derives "unreachable"
// once a daemon goes quiet, and a command expiring when its machine never
// answers, which no event announces.

export function issueEnvironmentsOptions(wsId: string, issueId: string) {
  return queryOptions({
    queryKey: issueKeys.environments(wsId, issueId),
    queryFn: () => api.listIssueEnvironments(issueId),
    enabled: !!wsId && !!issueId,
    refetchInterval: (query) => {
      const data = query.state.data;
      const pending = !!data && (
        data.pending_starts.length > 0 ||
        data.environments.some((env) => env.pending_action?.status === "pending")
      );
      return pending ? 5_000 : 60_000;
    },
  });
}

export function issueUsageOptions(issueId: string) {
  return queryOptions({
    queryKey: issueKeys.usage(issueId),
    queryFn: () => api.getIssueUsage(issueId),
  });
}

// Backs the description editor's fresh-sign download flow: NodeViews resolve
// an attachment id by matching the markdown URL against this list. The list
// is workspace-private metadata and lives on the same cache lifetime as the
// rest of the issue detail surface.

export function issueAttachmentsOptions(issueId: string) {
  return queryOptions({
    queryKey: issueKeys.attachments(issueId),
    queryFn: () => api.listAttachments(issueId),
  });
}

export function projectListOptions(wsId: string) {
  return queryOptions({
    queryKey: projectKeys.list(wsId),
    queryFn: () => api.listProjects({ include_archived: true }),
    select: (data) => data.projects,
  });
}

export function projectDetailOptions(wsId: string, id: string) {
  return queryOptions({
    queryKey: projectKeys.detail(wsId, id),
    queryFn: () => api.getProject(id),
  });
}

export function projectMembersOptions(wsId: string, id: string) {
  return queryOptions({
    queryKey: projectKeys.members(wsId, id),
    queryFn: () => api.getProjectMembers(id),
  });
}

export function privateProjectOverviewOptions(wsId: string) {
  return queryOptions({
    queryKey: projectKeys.privateOverview(wsId),
    queryFn: () => api.listPrivateProjectsForOwner(),
    select: (data) => data.projects,
  });
}

export function projectSubscriptionOptions(wsId: string, id: string) {
  return queryOptions({
    queryKey: projectKeys.subscription(wsId, id),
    queryFn: () => api.getProjectSubscription(id),
  });
}

export function workspaceListOptions() {
  return queryOptions({
    queryKey: workspaceKeys.list(),
    queryFn: () => api.listWorkspaces(),
  });
}

/** Resolves the workspace whose slug matches, from the cached workspace list. */

export function workspaceBySlugOptions(slug: string) {
  return queryOptions({
    ...workspaceListOptions(),
    select: (list: Workspace[]) => list.find((w) => w.slug === slug) ?? null,
  });
}

export function memberListOptions(wsId: string) {
  return queryOptions({
    queryKey: workspaceKeys.members(wsId),
    queryFn: () => api.listMembers(wsId),
  });
}

export function agentListOptions(wsId: string) {
  return queryOptions({
    queryKey: workspaceKeys.agents(wsId),
    queryFn: () =>
      api.listAgents({ workspace_id: wsId, include_archived: true }),
    // Projected unstable can age offline without an event; polling online also
    // covers a missed demotion. Offline recovery is event/reconnect-driven.
    refetchInterval: (query) =>
      query.state.data?.some(
        (agent) =>
          !agent.archived_at &&
          (agent.runtime_availability === "online" ||
            agent.runtime_availability === "unstable"),
      )
        ? 30_000
        : false,
  });
}

export function agentDetailOptions(wsId: string, agentId: string) {
  return queryOptions({
    queryKey: workspaceKeys.agent(wsId, agentId),
    queryFn: () => api.getAgent(agentId),
    enabled: !!wsId && !!agentId,
    retry: false,
  });
}

/**
 * Makes an authoritative agent response immediately visible to both agent
 * detail and list consumers. A cold list stays cold so one agent is never
 * mistaken for the complete workspace list.
 */

export function squadListOptions(wsId: string) {
  return queryOptions<Squad[]>({
    queryKey: workspaceKeys.squads(wsId),
    queryFn: () => api.listSquads(),
    enabled: !!wsId,
  });
}

/**
 * The squads behind the viewer's "my agents" relation, for evaluating it on
 * rows the client filters itself.
 */

export function involvedSquadIdsOptions(wsId: string) {
  return queryOptions({
    queryKey: workspaceKeys.involvedSquads(wsId),
    queryFn: () => api.listInvolvedSquadIds(),
    enabled: !!wsId,
  });
}

// Per-squad members status snapshot. The freshness signal is the WS task /
// agent / runtime invalidation wired in use-realtime-sync (which broadly
// invalidates `["workspaces", wsId, "squads"]`); the staleTime is a
// tab-focus safety net.

export function squadMemberStatusOptions(wsId: string, squadId: string) {
  return queryOptions({
    queryKey: workspaceKeys.squadMemberStatus(wsId, squadId),
    queryFn: () => api.getSquadMemberStatus(squadId),
    enabled: !!wsId && !!squadId,
    staleTime: 30 * 1000,
    refetchOnWindowFocus: true,
  });
}

export function skillListOptions(wsId: string) {
  return queryOptions({
    queryKey: workspaceKeys.skills(wsId),
    queryFn: () => api.listSkills(),
  });
}

export function skillDetailOptions(wsId: string, skillId: string) {
  return queryOptions({
    queryKey: [...workspaceKeys.skills(wsId), skillId] as const,
    queryFn: () => api.getSkill(skillId),
    enabled: !!skillId,
  });
}

// Nested under the skill detail key so skill realtime events, which
// invalidate the workspace skills prefix, refresh history too.

export function skillVersionsOptions(wsId: string, skillId: string) {
  return queryOptions({
    queryKey: [...workspaceKeys.skills(wsId), skillId, "versions"] as const,
    queryFn: () => api.listSkillVersions(skillId),
    enabled: !!skillId,
  });
}

// A version never changes once written.

export function skillVersionDetailOptions(
  wsId: string,
  skillId: string,
  version: number | null,
) {
  return queryOptions({
    queryKey: [...workspaceKeys.skills(wsId), skillId, "versions", version] as const,
    queryFn: () => api.getSkillVersion(skillId, version as number),
    enabled: !!skillId && version !== null,
    staleTime: Infinity,
  });
}

/**
 * Builds a `Map<skillId, Agent[]>` from the cached agent list. The server
 * already returns each agent with its full skill list inline, so no extra
 * request is needed — "which agents use skill X" is pure client-side fold.
 *
 * Exposed as a plain helper rather than a `queryOptions` with `select` so
 * the Map's identity is stable across unrelated agent-cache rerenders —
 * callers wrap this in `useMemo(..., [agents])` and only re-fold when the
 * agent array identity actually changes. Previously this was `{ select }`,
 * which returned a new Map every subscription tick and triggered cascading
 * re-renders on every `agent:updated` WS event.
 */

export function invitationListOptions(wsId: string) {
  return queryOptions({
    queryKey: workspaceKeys.invitations(wsId),
    queryFn: () => api.listWorkspaceInvitations(wsId),
  });
}

export function shareLinkListOptions(wsId: string, enabled = true) {
  return queryOptions({
    queryKey: workspaceKeys.shareLinks(wsId),
    queryFn: () => api.listShareLinks(wsId),
    enabled: enabled && !!wsId,
  });
}

export function myInvitationListOptions() {
  return queryOptions({
    queryKey: workspaceKeys.myInvitations(),
    queryFn: () => api.listMyInvitations(),
    // Recover missed realtime events without refetching on every tab switch.
    staleTime: 30 * 1000,
    refetchOnWindowFocus: true,
  });
}

export function assigneeFrequencyOptions(wsId: string) {
  return queryOptions({
    queryKey: workspaceKeys.assigneeFrequency(wsId),
    queryFn: () => api.getAssigneeFrequency(),
  });
}

/**
 * The workspace's MCP server library. Fetched for plain members too — the
 * payload is names and transports only, and an agent owner needs to see what
 * is available to assign.
 */

export function workspaceMcpServersOptions(wsId: string) {
  return queryOptions({
    queryKey: workspaceKeys.mcpServers(wsId),
    queryFn: () => api.listWorkspaceMcpServers(wsId),
    enabled: wsId !== "",
  });
}

/** The workspace MCP servers assigned to one agent, with their toggles. */

export function agentMcpServersOptions(agentId: string) {
  return queryOptions({
    queryKey: ["agents", agentId, "mcp-servers"] as const,
    queryFn: () => api.listAgentMcpServers(agentId),
    enabled: agentId !== "",
  });
}

export function issueStatusListOptions(wsId: string) {
  return queryOptions({
    queryKey: issueStatusKeys.list(wsId),
    // ARCHIVED entries included on purpose. Archiving retires a status from
    // future assignment but leaves existing issues on it, and those issues must
    // keep their real name, color and category. Dropping archived rows here
    // would degrade them to a raw key with a guessed category. Pickers use
    // `activeStatuses`, which excludes them. (MUL-6243)
    queryFn: () => api.listIssueStatuses(true),
    select: (data) => data.statuses,
    // The catalog changes only when an admin edits it, which is rare, so a
    // generous stale time keeps this off the critical path of every render
    // that needs a status label.
    staleTime: 5 * 60_000,
  });
}

/**
 * A resolved view over the catalog. Every lookup falls back to something
 * renderable, because an issue can legitimately carry a status this client has
 * not heard of: a status created moments ago in another session, or one whose
 * catalog fetch has not landed yet.
 */
export interface IssueStatusCatalog {
  /**
   * Every status in display order, ARCHIVED INCLUDED, so an issue left on an
   * archived status still resolves to its real name, color and category.
   * For anything that offers a status to pick, use `activeStatuses`.
   */
  statuses: IssueStatusEntry[];
  /** Assignable statuses — `statuses` minus archived ones. */
  activeStatuses: IssueStatusEntry[];
  /** Category for a status key; falls back to the built-in map, else "unstarted". */
  categoryOf: (statusKey: string) => IssueStatusCategory;
  /** Human label for a status key; falls back to the category label, then the raw key. */
  labelOf: (statusKey: string) => string;
  /** Catalog entry for a status key, when the catalog knows it. */
  entryOf: (statusKey: string) => IssueStatusEntry | undefined;
  /**
   * The `#rrggbb` a surface must paint a status with, or null when it keeps
   * its category's semantic token.
   *
   * ALWAYS null for a built-in. The seven built-ins carry a seeded hex in the
   * catalog, but they are not recolorable (the server rejects any edit to a
   * system row) and every surface renders them from the token — `text-success`
   * and friends, which is what makes them follow the theme into dark mode. A
   * caller that reaches for `entryOf(key)?.color` instead paints the raw seed
   * and drifts from the same status two pixels away. (MUL-6440)
   */
  colorOf: (statusKey: string) => string | null;
  /** Custom visual geometry; null keeps the default. Never drives behavior. */
  iconOf: (statusKey: string) => string | null;
  /** ACTIVE statuses belonging to one category, in display order. */
  inCategory: (category: IssueStatusCategory) => IssueStatusEntry[];
  /** True once the catalog has loaded; false while it is still in flight. */
  isLoaded: boolean;
  /**
   * The catalog is still in flight and nothing has resolved yet.
   *
   * A surface that routes on a CUSTOM status key has to hold its loading state
   * while this is true. `isLoaded === false` alone is not enough to act on:
   * the difference between "not here yet" and "the request failed" decides
   * whether the user sees a spinner or a retryable error, and the first cut
   * showed neither — just a silently empty board. (MUL-6243)
   */
  isPending: boolean;
  /**
   * The catalog request failed AND there is no usable snapshot to fall back on.
   *
   * Narrower than "the query errored" on purpose: a BACKGROUND refetch can fail
   * while the last successful catalog is still cached, and blocking a surface
   * then would throw away data that is perfectly serviceable. Only a failure
   * with nothing behind it is worth stopping for. (MUL-6243)
   */
  isError: boolean;
  /** Re-runs the catalog request. Wired to the surface's retry affordance. */
  retry: () => void;
  /**
   * True when the catalog is LOADED and holds at least one custom status.
   *
   * This is the switch for the category-grouped surface contract. Two reasons
   * it has to be both conditions:
   *
   * - Rolling deploy. `group.kind=status_category` is a server contract this
   *   feature introduced, so a client that sends it unconditionally 400s
   *   against any pod that has not been updated yet. A workspace only HAS a
   *   custom status once the creation flag was on, which means the fleet was
   *   already serving this version.
   * - Cold load. Until the catalog lands, `categoryOf` cannot tell a custom key
   *   from an unknown one and falls back to `unstarted`. Routing on that guess
   *   sends a saved `qa` filter to the wrong column and renders an empty board.
   *
   * Retained for callers that need to distinguish whether a workspace has
   * extended its status vocabulary. (MUL-6243)
   */
  hasCustomStatuses: boolean;
}

const BUILT_IN = new Set<string>(BUILT_IN_STATUS_ORDER);
const CATEGORY = new Set<string>(STATUS_ORDER);

const CATEGORY_RANK = new Map<string, number>(STATUS_ORDER.map((c, i) => [c, i]));
const BUILT_IN_RANK = new Map<string, number>(
  BUILT_IN_STATUS_ORDER.map((status, index) => [status, index]),
);

/**
 * The server's catalog ordering, mirrored for client-side re-sorts.
 * Category rank, then intra-category position, then built-in rank/key to break ties —
 * see `ListIssueStatusEntries` in `issue_status.sql`. An optimistic reorder has
 * to re-sort with this or the new positions land in the cache while the list
 * still renders in the old order.
 */
